class InvariantErr(Exception):
    """Raised when safety-critical invariant checks fail."""
    pass


class ModuleV2_08:
    """Safety-Critical Controls Module V2_08."""

    @staticmethod
    def check_invariant(p: dict) -> bool:
        """
        Enforces that check_invariant(p) returns True for p.get('valid') == True,
        and raises InvariantErr otherwise.
        """
        if p.get('valid') is True:
            return True
        raise InvariantErr("Invariant check failed: 'valid' parameter is not True.")
